  async function lock(it) { const v = await SUITE.dialog({ title: "Lock \"" + it.name + "\"", text: "The file is sealed on this device with the password before it is stored. Nobody else can open it without the password — not an administrator, not the software owner. If the password is lost, the file is lost.", fields: [{ k: "a", label: "Password", type: "password" }, { k: "b", label: "Repeat password", type: "password" }], ok: "Lock", validate: (x) => { if (x.a.length < 4) throw new Error("Use at least 4 characters"); if (x.a !== x.b) throw new Error("The passwords differ"); } }); if (!v) return; try { SUITE.toast("Sealing…"); const b = await VDB.get(it); const sealed = await SUITE.crypto.seal(b, v.a); await VDB.put(it, sealed); const row = await VDB.update(it.id, { locked: true, enc: { v: 1, alg: "AES-GCM-256/PBKDF2" } }); Object.assign(it, row || { locked: true }); st.pw[it.id] = v.a; delete st.cache[it.id]; draw(); SUITE.toast(it.name + " is locked"); } catch (e) { SUITE.toast("Lock failed: " + e.message); } }
