  async function summary() { try { const rows = await VDB.list(); const files = rows.filter((x) => x.kind === "file" && !x.deleted_at && (x.scope === "shared" || x.owner_id === me())); const used = files.reduce((k, x) => k + (+x.size || 0), 0); if (!files.length) return "No files yet"; const last = files.map((x) => x.updated_at || "").sort().pop(); return files.length + " file" + (files.length === 1 ? "" : "s") + " · " + SUITE.fmtBytes(used) + " · " + SUITE.ago(last); } catch (e) { return ""; } }
  const help = () => [["Private, people, Company", "Everything you add is private unless you say otherwise. " + (company() ? "⋯ → Share with people… opens a private file or folder to the colleagues you pick (they find it under Shared with me; Stop sharing takes it back). Move to Company… puts it in the company area, where everyone in " + coName() + " who has DOCUMENTS sees and changes it; Make private brings it back. The badge on every row says who sees it." : "Files on this device are yours alone.")], ["Folders", "New folder in the header; folders inside folders; the tree on the left and the breadcrumbs move around. Backspace goes up."], ["Uploading", "Upload in the header, or drop files anywhere on the list. Same name in the same folder asks before replacing."], ["Opening", SUITE.host && SUITE.host.openNative ? (SUITE.host.mobile ? "Open hands the file to the app on this device that owns it, or to the share sheet." : "Double-click (or Enter) hands the file to the app this computer opens it with — Excel, Word, the PDF reader, the image viewer; when you save there, the saved file goes back here within seconds. Files you may only read open as a copy. Programs and scripts (.exe, .bat, .js, .sh and the like) are never opened: XYNTAX offers Save as… instead.") : "Open hands the file to the app on this device that owns it, or to the share sheet."], ["Preview", "Click a file: images, PDFs, text, CSV, audio and video preview on the right." + (onDesktop() ? " Space (or ⋯ → Preview) shows the selected file full-size inside XYNTAX without opening another app." : "")], ["Locking", "⋯ → Lock with a password seals the file on your device before it is stored; nobody can open it without the password — if it is lost, the file is lost."], ["Selecting", "Tick boxes (or Shift/Ctrl-click rows) to move, download or trash several at once."], ["Trash", "Deleted items wait 30 days; restore or delete for good. Delete key trashes the selected item, Enter opens it."]];
